import{_ as i,a0 as o,w as d,s as r,I as a,x as n,a1 as p,A as l,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"用 OpenSSL 替代 telnet | LCTT x X-CMD","titleTemplate":false,"description":"用 OpenSSL 替代 telnet | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 OpenSSL 替代 telnet | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 OpenSSL 替代 telnet | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210505 Drop telnet for OpenSSL","title":"用 OpenSSL 替代 telnet","tag":"202105","desc":""},"relativePath":"202105/20210505 Drop telnet for OpenSSL.md","filePath":"[post].md"}'),g={name:"202105/20210505 Drop telnet for OpenSSL.md"};function c(h,s,u,b,m,k){const e=o("Link");return d(),r("div",null,[s[36]||(s[36]=a("h1",{id:"用-openssl-替代-telnet",tabindex:"-1"},[n("用 OpenSSL 替代 telnet "),a("a",{class:"header-anchor",href:"#用-openssl-替代-telnet","aria-label":"Permalink to “用 OpenSSL 替代 telnet”"},"​")],-1)),s[37]||(s[37]=a("blockquote",null,[a("p",null,"Telnet 缺乏加密，這使得 OpenSSL 成為連接遠程系統的更安全的選擇。")],-1)),s[38]||(s[38]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202105/11/115934cggzmq8rm8suaqlq.png",alt:""})],-1)),a("p",null,[p(e,{href:"https://www.redhat.com/sysadmin/telnet-netcat-troubleshooting"},{default:l(()=>[...s[0]||(s[0]=[n("telnet",-1)])]),_:1}),s[1]||(s[1]=n(" 命令是最受歡迎的網絡故障排除工具之一，從系統管理員到網絡愛好者都可以使用。在網絡計算的早期，",-1)),s[2]||(s[2]=a("code",null,"telnet",-1)),s[3]||(s[3]=n(" 被用來連接到一個遠程系統。你可以用 ",-1)),s[4]||(s[4]=a("code",null,"telnet",-1)),s[5]||(s[5]=n(" 訪問一個遠程系統的端口，登錄並在該主機上運行命令。",-1))]),s[39]||(s[39]=t('<p>由於 <code>telnet</code> 缺乏加密功能，它在很大程度上已經被 OpenSSL 取代了這項工作。然而，作為一種智能的 <code>ping</code>，<code>telnet</code> 的作用仍然存在（甚至在某些情況下至今仍然存在）。雖然 <code>ping</code> 命令是一個探測主機響應的好方法，但這是它能做的 <em>全部</em>。另一方面，<code>telnet</code> 不僅可以確認一個活動端口，而且還可以與該端口的服務進行交互。即便如此，由於大多數現代網絡服務都是加密的，<code>telnet</code> 的作用可能要小得多，這取決於你想實現什麼。</p><h3 id="openssl-s-client" tabindex="-1">OpenSSL s_client <a class="header-anchor" href="#openssl-s-client" aria-label="Permalink to “OpenSSL s_client”">​</a></h3>',2)),a("p",null,[s[8]||(s[8]=n("對於大多數曾經需要 ",-1)),s[9]||(s[9]=a("code",null,"telnet",-1)),s[10]||(s[10]=n(" 的任務，我現在使用 OpenSSL 的 ",-1)),s[11]||(s[11]=a("code",null,"s_client",-1)),s[12]||(s[12]=n(" 命令。（我在一些任務中使用 ",-1)),p(e,{href:"https://opensource.com/downloads/curl-command-cheat-sheet"},{default:l(()=>[...s[6]||(s[6]=[n("curl",-1)])]),_:1}),s[13]||(s[13]=n("，但那些情況下我可能無論如何也不會使用 ",-1)),s[14]||(s[14]=a("code",null,"telnet",-1)),s[15]||(s[15]=n("）。大多數人都知道 ",-1)),p(e,{href:"https://www.openssl.org/"},{default:l(()=>[...s[7]||(s[7]=[n("OpenSSL",-1)])]),_:1}),s[16]||(s[16]=n(" 是一個加密的庫和框架，但不是所有人都意識到它也是一個命令。",-1)),s[17]||(s[17]=a("code",null,"openssl",-1)),s[18]||(s[18]=n(" 命令的 ",-1)),s[19]||(s[19]=a("code",null,"s_client",-1)),s[20]||(s[20]=n(" 組件實現了一個通用的 SSL 或 TLS 客户端，幫助你使用 SSL 或 TLS 連接到遠程主機。它是用來測試的，至少在內部使用與該庫相同的功能。",-1))]),s[40]||(s[40]=t(`<h3 id="安裝-openssl" tabindex="-1">安裝 OpenSSL <a class="header-anchor" href="#安裝-openssl" aria-label="Permalink to “安裝 OpenSSL”">​</a></h3><p>OpenSSL 可能已經安裝在你的 Linux 系統上了。如果沒有，你可以用你的發行版的軟件包管理器安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install openssl</span></span></code></pre></div><p>在 Debian 或類似的系統上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install openssl</span></span></code></pre></div><p>安裝後，驗證它的響應是否符合預期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl version</span></span>
<span class="line"><span>OpenSSL x.y.z FIPS</span></span></code></pre></div><h3 id="驗證端口訪問" tabindex="-1">驗證端口訪問 <a class="header-anchor" href="#驗證端口訪問" aria-label="Permalink to “驗證端口訪問”">​</a></h3><p>最基本的 <code>telnet</code> 用法是一個看起來像這樣的任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ telnet mail.example.com 25</span></span>
<span class="line"><span>Trying 98.76.54.32...</span></span>
<span class="line"><span>Connected to example.com.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span></code></pre></div><p>在此示例中，這將與正在端口 25（可能是郵件服務器）監聽的任意服務打開一個交互式會話。只要你獲得訪問權限，就可以與該服務進行通信。</p><p>如果端口 25 無法訪問，連接就會被拒絕。</p><p>OpenSSL 也是類似的，儘管通常較少互動。要驗證對一個端口的訪問：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl s_client -connect example.com:80</span></span>
<span class="line"><span>CONNECTED(00000003)</span></span>
<span class="line"><span>140306897352512:error:1408F10B:SSL [...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>no peer certificate available</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No client certificate CA names sent</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SSL handshake has read 5 bytes and written 309 bytes</span></span>
<span class="line"><span>Verification: OK</span></span>
<span class="line"><span></span></span>
<span class="line"><span>New, (NONE), Cipher is (NONE)</span></span>
<span class="line"><span>Secure Renegotiation IS NOT supported</span></span>
<span class="line"><span>Compression: NONE</span></span>
<span class="line"><span>Expansion: NONE</span></span>
<span class="line"><span>No ALPN negotiated</span></span>
<span class="line"><span>Early data was not sent</span></span>
<span class="line"><span>Verify return code: 0 (ok)</span></span></code></pre></div><p>但是，這僅是目標性 <code>ping</code>。從輸出中可以看出，沒有交換 SSL 證書，所以連接立即終止。為了充分利用 <code>openssl s_client</code>，你必須連接加密的端口。</p><h3 id="交互式-openssl" tabindex="-1">交互式 OpenSSL <a class="header-anchor" href="#交互式-openssl" aria-label="Permalink to “交互式 OpenSSL”">​</a></h3><p>Web 瀏覽器和 Web 服務器進行交互，可以使指向 80 端口的流量實際上被轉發到 443，這是保留給加密 HTTP 流量的端口。知道了這一點，你就可以用 <code>openssl</code> 命令連接到加密的端口，並與在其上運行的任何網絡服務進行交互。</p><p>首先，使用 SSL 連接到一個端口。使用 <code>-showcerts</code> 選項會使 SSL 證書打印到你的終端上，一開始的輸出要比 telnet 要冗長得多：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl s_client -connect example.com:443 -showcerts</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>    0080 - 52 cd bd 95 3d 8a 1e 2d-3f 84 a0 e3 7a c0 8d 87   R...=..-?...z...</span></span>
<span class="line"><span>    0090 - 62 d0 ae d5 95 8d 82 11-01 bc 97 97 cd 8a 30 c1   b.............0.</span></span>
<span class="line"><span>    00a0 - 54 78 5c ad 62 5b 77 b9-a6 35 97 67 65 f5 9b 22   Tx\\\\.b[w..5.ge..&quot;</span></span>
<span class="line"><span>    00b0 - 18 8a 6a 94 a4 d9 7e 2f-f5 33 e8 8a b7 82 bd 94   ..j...~/.3......</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Start Time: 1619661100</span></span>
<span class="line"><span>    Timeout   : 7200 (sec)</span></span>
<span class="line"><span>    Verify return code: 0 (ok)</span></span>
<span class="line"><span>    Extended master secret: no</span></span>
<span class="line"><span>    Max Early Data: 0</span></span>
<span class="line"><span>-</span></span>
<span class="line"><span>read R BLOCK</span></span></code></pre></div><p>你被留在一個交互式會話中。最終，這個會話將關閉，但如果你及時行動，你可以向服務器發送 HTTP 信號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>GET / HTTP/1.1</span></span>
<span class="line"><span>HOST: example.com</span></span></code></pre></div><p>按<strong>回車鍵</strong>兩次，你會收到 <code>example.com/index.html</code> 的數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>&lt;body&gt;</span></span>
<span class="line"><span>&lt;div&gt;</span></span>
<span class="line"><span>    &lt;h1&gt;Example Domain&lt;/h1&gt;</span></span>
<span class="line"><span>    &lt;p&gt;This domain is for use in illustrative examples in documents. You may use this</span></span>
<span class="line"><span>    domain in literature without prior coordination or asking for permission.&lt;/p&gt;</span></span>
<span class="line"><span>    &lt;p&gt;&lt;a href=&quot;https://www.iana.org/domains/example&quot;&gt;More information...&lt;/a&gt;&lt;/p&gt;</span></span>
<span class="line"><span>&lt;/div&gt;</span></span>
<span class="line"><span>&lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><h4 id="email-服務器" tabindex="-1">Email 服務器 <a class="header-anchor" href="#email-服務器" aria-label="Permalink to “Email 服務器”">​</a></h4><p>你也可以使用 OpenSSL 的 <code>s_client</code> 來測試一個加密的 Email 服務器。要做到這點，你必須把你的測試用户的用户名和密碼用 Base64 編碼。</p><p>這裏有一個簡單的方法來做到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ perl -MMIME::Base64 -e &#39;print encode_base64(&quot;username&quot;);&#39;</span></span>
<span class="line"><span>$ perl -MMIME::Base64 -e &#39;print encode_base64(&quot;password&quot;);&#39;</span></span></code></pre></div><p>當你記錄了這些值，你就可以通過 SSL 連接到郵件服務器，它通常在 587 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl s_client -starttls smtp \\</span></span>
<span class="line"><span>-connect email.example.com:587</span></span>
<span class="line"><span>&gt; ehlo example.com</span></span>
<span class="line"><span>&gt; auth login</span></span>
<span class="line"><span>##paste your user base64 string here##</span></span>
<span class="line"><span>##paste your password base64 string here##</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; mail from: noreply@example.com</span></span>
<span class="line"><span>&gt; rcpt to: admin@example.com</span></span>
<span class="line"><span>&gt; data</span></span>
<span class="line"><span>&gt; Subject: Test 001</span></span>
<span class="line"><span>This is a test email.</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>&gt; quit</span></span></code></pre></div><p>檢查你的郵件（在這個示例代碼中，是 <code>admin@example.com</code>），查看來自 <code>noreply@example.com</code> 的測試郵件。</p><h3 id="openssl-還是-telnet" tabindex="-1">OpenSSL 還是 Telnet？ <a class="header-anchor" href="#openssl-還是-telnet" aria-label="Permalink to “OpenSSL 還是 Telnet？”">​</a></h3><p><code>telnet</code> 仍然有用途，但它已經不是以前那種不可缺少的工具了。該命令在許多發行版上被歸入 “遺留” 網絡軟件包，而且還沒有 <code>telnet-ng</code> 之類的明顯的繼任者，管理員有時會對它被排除在默認安裝之外感到疑惑。答案是，它不再是必不可少的，它的作用越來越小，這 <em>很好</em>。網絡安全很重要，所以要適應與加密接口互動的工具，這樣你就不必在排除故障時禁用你的保護措施。</p><hr>`,33)),a("p",null,[s[22]||(s[22]=n("via: ",-1)),p(e,{href:"https://opensource.com/article/21/5/drop-telnet-openssl"},{default:l(()=>[...s[21]||(s[21]=[n("https://opensource.com/article/21/5/drop-telnet-openssl",-1)])]),_:1})]),a("p",null,[s[27]||(s[27]=n("作者：",-1)),p(e,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[23]||(s[23]=[n("Seth Kenlon",-1)])]),_:1}),s[28]||(s[28]=n(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[24]||(s[24]=[n("lujun9972",-1)])]),_:1}),s[29]||(s[29]=n(" 譯者：",-1)),p(e,{href:"https://github.com/geekpi"},{default:l(()=>[...s[25]||(s[25]=[n("geekpi",-1)])]),_:1}),s[30]||(s[30]=n(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[26]||(s[26]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[33]||(s[33]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[31]||(s[31]=[n("LCTT",-1)])]),_:1}),s[34]||(s[34]=n(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:l(()=>[...s[32]||(s[32]=[n("Linux中國",-1)])]),_:1}),s[35]||(s[35]=n(" 榮譽推出",-1))])])}const T=i(g,[["render",c]]);export{x as __pageData,T as default};
